$root=Split-Path $PSScriptRoot -Parent; . "$PSScriptRoot\lib\Common.ps1"; . "$PSScriptRoot\lib\Config.ps1"; . "$PSScriptRoot\lib\Network.ps1"; . "$PSScriptRoot\lib\GitHubRelease.ps1"; . "$PSScriptRoot\lib\ScheduledTask.ps1"; Assert-WindowsX64; Assert-Administrator; Initialize-CPAStackLayout|Out-Null; Initialize-CPAConfig $root; Import-CPAStackProxy; if(!(Test-Path (Join-Path (Get-CPAStackRoot) 'config\proxy.psd1'))){Set-CPAStackProxy}; foreach($s in 'cli','keeper'){Write-Host "Installing $s..."; Install-VerifiedRelease $s|Out-Null}; Register-CPAStackTasks $root; foreach($s in 'cli','keeper'){Start-CPAStackService $s}; Write-Host 'CPAStack installed.'
